const lessons=[{"sentences":[{"speaker":"A","text":"We need to plan something special for Sarah because her birthday is coming up next week.","position":1,"audioStartSeconds":0,"audioEndSeconds":5.43025},{"speaker":"B","text":"I completely agree since she always makes our birthdays so memorable.","position":2,"audioStartSeconds":5.63025,"audioEndSeconds":10.261541666666666},{"speaker":"A","text":"Should we host a dinner party at my apartment or reserve a table at a restaurant?","position":3,"audioStartSeconds":10.461541666666667,"audioEndSeconds":15.346333333333334},{"speaker":"B","text":"Cooking at home would be much cheaper although it requires a lot of preparation.","position":4,"audioStartSeconds":15.546333333333333,"audioEndSeconds":20.379583333333333},{"speaker":"A","text":"My kitchen is rather small so cooking for ten people might become quite stressful.","position":5,"audioStartSeconds":20.579583333333332,"audioEndSeconds":26.004833333333334},{"speaker":"B","text":"We could order some pizzas if everyone agrees to keep the food casual and simple.","position":6,"audioStartSeconds":26.204833333333333,"audioEndSeconds":31.398125},{"speaker":"A","text":"Ordering pizza is a wonderful idea because it saves us from spending hours washing dishes.","position":7,"audioStartSeconds":31.598125,"audioEndSeconds":37.564625},{"speaker":"B","text":"How much money can we afford to spend on this gathering altogether?","position":8,"audioStartSeconds":37.764625,"audioEndSeconds":42.055875},{"speaker":"A","text":"I checked my savings and I can comfortably contribute fifty dollars to the total budget.","position":9,"audioStartSeconds":42.255875,"audioEndSeconds":47.835791666666665},{"speaker":"B","text":"I can match that amount so we have one hundred dollars in total for food and drinks.","position":10,"audioStartSeconds":48.03579166666667,"audioEndSeconds":53.03579166666667},{"speaker":"A","text":"That budget should easily cover four large pizzas and several bottles of sparkling juice.","position":11,"audioStartSeconds":53.235791666666664,"audioEndSeconds":59.189375},{"speaker":"B","text":"We should also buy a nice chocolate cake from the local bakery downtown.","position":12,"audioStartSeconds":59.389375,"audioEndSeconds":63.83525},{"speaker":"A","text":"Sarah loves chocolate so she will definitely appreciate that thoughtful sweet treat.","position":13,"audioStartSeconds":64.03525,"audioEndSeconds":69.177},{"speaker":"B","text":"Let us create a group chat tonight to ask our friends about their favorite toppings.","position":14,"audioStartSeconds":69.377,"audioEndSeconds":74.20945833333333},{"speaker":"A","text":"I will send out the messages right now while you browse the bakery website.","position":15,"audioStartSeconds":74.40945833333333,"audioEndSeconds":79.07358333333333},{"speaker":"B","text":"Everything sounds fully organized now and we are ready to throw a fantastic party.","position":16,"audioStartSeconds":79.27358333333333,"audioEndSeconds":84.55629166666667}],"questions":[{"prompt":"What is the primary purpose of the conversation?","options":["To plan a surprise birthday gathering for Sarah.","To discuss recipes for a homemade dinner party.","To complain about the cost of restaurant tables."],"answer":"A","evidenceSentence":1,"evidence":"We need to plan something special for Sarah because her birthday is coming up next week.","explanation":"Hai người bạn bắt đầu cuộc trò chuyện với mục đích lên kế hoạch cho sinh nhật của Sarah."},{"prompt":"Why did they decide against cooking at home?","options":["The ingredients were too expensive.","The kitchen was too small for ten guests.","Neither of them knew how to bake a cake."],"answer":"B","evidenceSentence":5,"evidence":"My kitchen is rather small so cooking for ten people might become quite stressful.","explanation":"Nhân vật A giải thích rằng bếp khá nhỏ nên nấu ăn cho mười người sẽ rất căng thẳng."},{"prompt":"What food did they ultimately decide to order?","options":["Homemade pasta.","Restaurant steaks.","Pizzas."],"answer":"C","evidenceSentence":6,"evidence":"We could order some pizzas if everyone agrees to keep the food casual and simple.","explanation":"Họ đồng ý gọi bánh pizza để giữ mọi thứ đơn giản và thoải mái."},{"prompt":"How much money do they have available in total for the party?","options":["Fifty dollars.","One hundred dollars.","One hundred and fifty dollars."],"answer":"B","evidenceSentence":10,"evidence":"I can match that amount so we have one hundred dollars in total for food and drinks.","explanation":"Mỗi người góp năm mươi đô la, tổng cộng là một trăm đô la."},{"prompt":"What extra item do they plan to purchase from the bakery?","options":["A chocolate cake.","Fresh fruit tarts.","Vanilla cupcakes."],"answer":"A","evidenceSentence":12,"evidence":"We should also buy a nice chocolate cake from the local bakery downtown.","explanation":"Họ quyết định mua một chiếc bánh sô-cô-la ở tiệm bánh địa phương."},{"prompt":"What will speaker A do immediately after the conversation?","options":["Browse the bakery website.","Order the pizzas online.","Send out messages in a group chat."],"answer":"C","evidenceSentence":15,"evidence":"I will send out the messages right now while you browse the bakery website.","explanation":"Nhân vật A nhận việc gửi tin nhắn ngay lập tức trong khi bạn mình xem trang web tiệm bánh."}]}];const cards=[...document.querySelectorAll('article')];let stopping=null,stoppingAudio=null;
    document.addEventListener('play',event=>{if(event.target.tagName!=='AUDIO')return;document.querySelectorAll('audio').forEach(a=>{if(a!==event.target)a.pause()})},true);
    document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{let count=0;cards.forEach(c=>{c.hidden=button.dataset.filter!=='ALL'&&c.dataset.goal!==button.dataset.filter;if(!c.hidden)count++;else c.querySelector('audio').pause()});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button));document.querySelector('#filter-status').textContent='Đang hiển thị '+count+' bài.'});
    const normal=value=>value.trim().toLowerCase().replace(/\s+/g,' ');
    document.querySelectorAll('[data-check]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.check);let score=0;lessons[i].questions.forEach((q,n)=>{const value=normal(document.getElementById('answer-'+i+'-'+n).value);if([q.answer,...(q.accepted||[])].some(a=>normal(a)===value))score++});document.getElementById('result-'+i).textContent=score+'/'+lessons[i].questions.length+' câu đúng. Mở phần đáp án để xem giải thích.'});
    document.querySelectorAll('[data-segment]').forEach(button=>button.onclick=async()=>{if(stopping)stopping();const [i,n]=button.dataset.segment.split(',').map(Number),audio=cards[i].querySelector('audio'),s=lessons[i].sentences[n];audio.currentTime=s.audioStartSeconds;const stop=()=>{stopping=null;stoppingAudio=null;audio.removeEventListener('timeupdate',check);audio.pause()},check=()=>{if(audio.currentTime>=s.audioEndSeconds)stop()};stopping=stop;stoppingAudio=audio;audio.addEventListener('timeupdate',check);try{await audio.play()}catch(_){stop();document.getElementById('result-'+i).textContent='Không phát được audio. Hãy dùng nút tải WAV để nghe.'}});
    document.querySelectorAll('audio').forEach(audio=>audio.addEventListener('pause',()=>{if(audio.paused&&stoppingAudio===audio&&stopping)stopping()}));
const authStatus=document.querySelector('#auth-status');
async function initializeAudio(){
 try{
  const response=await fetch('/api/auth/me',{credentials:'same-origin'});
  if(response.status===401){authStatus.hidden=false;authStatus.innerHTML='Đăng nhập để nghe audio. <a href="/login?next=%2Fcatalog%3Fgoal%3DALL">Đăng nhập</a> rồi mở bài từ thư viện bằng nút “Nghe toàn bài & làm câu hỏi”.';return}
  if(!response.ok)throw Error('account');
  document.querySelectorAll('audio').forEach(audio=>{audio.src=audio.dataset.src;audio.preload='none';audio.hidden=false});
  document.querySelectorAll('[data-segment]').forEach(button=>button.disabled=false);
  document.querySelectorAll('a[download]').forEach(link=>link.hidden=false);
 }catch(_){authStatus.hidden=false;authStatus.textContent='Không kiểm tra được đăng nhập. Hãy tải lại trang để thử lại.'}
}
initializeAudio();
